```java
public static boolean isPowerOfThree(int n) {
    if (n <= 0 || n > Integer.MAX_VALUE / 3) {
        // n must be a positive integer less than or equal to 2^31 - 1 / 3
        return false;
    }

    int left = 0;
    int right = 32;

    while (left <= right) {
        int mid = (left + right) / 2;

        if (Math.pow(3, mid) == n) {
            return true;
        } else if (Math.pow(3, mid) < n) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return false;
