```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

using namespace std;

int main() {
    string word; // слово, которое необходимо найти в файле
    int count = 0; // количество вхождений слова в файл

    // Ввод слова, которое необходимо найти в файле
    cout << "Enter the word to search: ";
    cin >> word;

    // Открытие файла для чтения
    string filename;
    cout << "Enter the filename: ";
    cin >> filename;
    ifstream file(filename);

    // Проверка успешности открытия файла
    if (!file.is_open()) {
        cerr << "Error: unable to open file " << filename << endl;
        return 1;
    }

    // Чтение файла построчно и подсчет вхождений слова
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(word, pos)) != string::npos) {
            count++;
            pos += word.length();
        }
    }

    // Вывод результата
    cout << "The word \"" << word << "\" appears " << count << " times in the file " << filename << endl;

